document.addEventListener('change',e=>{if(e.target.id==='pop-min'){state.rootPage=1;renderRoots()}if(e.target.id==='root-sort'){state.sort=e.target.value;state.rootPage=1;renderRoots()}if(e.target.name==='sort'){state.sort=e.target.value;state.rootPage=1;renderRoots()}if(e.target.id==='page-size'){state.pageSize=+e.target.value;state.page=1;renderKeywords()}if(e.target.id==='page-go'){state.page=+e.target.value;renderKeywords()}if(e.target.id==='uncovered')renderRoots();if(e.target.name==='chart-metric'){state.chartMetric=+e.target.value;renderTrend()}if(e.target.id==='file-input'&&e.target.files[0]){e.target.files[0].text().then(text=>{prepareData(JSON.parse(text));state.selected=[];state.page=1;renderDate();renderRoots();renderKeywords();$('#info-overlay').hidden=true;toast('数据快照已载入；下载快照可留存本次数据。')}).catch(err=>toast('导入失败：'+err.message))}});
