function localRead(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function localWrite(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function showView(view,updateHash=true){const target=['keywords','demand','price'].includes(view)?view:'dashboard',hash=target==='dashboard'?'home':target;$$('.app-view').forEach(el=>el.hidden=el.id!==({keywords:'keyword-view',demand:'demand-view',price:'price-view',dashboard:'dashboard-view'}[target]));$$('.sidebar [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===target));if(updateHash&&location.hash!=='#'+hash)history.replaceState(null,'','#'+hash);if(target==='keywords'&&DATA)renderRoots();document.title=({dashboard:'电商运营工作台',keywords:'关键词机会中心',demand:'需求分类',price:'价格带洞察'})[target]+' · Boundary BI';window.scrollTo({top:0,behavior:'smooth'})}
function trackTool(id,name,url='',view=''){let recent=localRead('boundary-recent-tools',[]).filter(item=>item.id!==id);recent.unshift({id,name,url,view});localWrite('boundary-recent-tools',recent.slice(0,4));renderRecentTools()}
function renderRecentTools(){const recent=localRead('boundary-recent-tools',[]),wrap=$('#recent-tools');if(!wrap)return;wrap.innerHTML=recent.length?recent.map((item,i)=>`<button data-recent-tool="${i}">${esc(item.name)}</button>`).join(''):'<span>使用工具后会显示在这里</span>'}
function renderDashboardStats(){if(!CATALOG)return;const categories=Object.values(CATALOG.categories||{}),available=categories.filter(c=>['complete','partial'].includes(c.collectionStatus)).length,maxMonths=Math.max(0,...categories.map(c=>Object.keys(c.monthData||{}).length));$('#stat-categories').textContent=available;$('#stat-months').textContent=maxMonths}
function nextAnnual(month,day){const now=new Date(),candidate=new Date(now.getFullYear(),month-1,day,23,59,59);if(candidate<now)candidate.setFullYear(candidate.getFullYear()+1);return candidate}
function nextFathersDay(){const now=new Date();for(let year=now.getFullYear();year<=now.getFullYear()+1;year++){const first=new Date(year,5,1),day=1+(7-first.getDay())%7+14,target=new Date(year,5,day,23,59,59);if(target>=now)return target}}
function renderCountdowns(){const fixed=[['双11',()=>nextAnnual(11,11)],['双12',()=>nextAnnual(12,12)],['618',()=>nextAnnual(6,18)],['父亲节',nextFathersDay]].map(([name,get])=>({name,date:get(),fixed:true})),custom=localRead('boundary-countdowns',[]).map((item,index)=>({...item,date:new Date(item.date+'T23:59:59'),index})).filter(item=>!Number.isNaN(item.date.getTime())&&item.date>=new Date(new Date().setHours(0,0,0,0))),items=[...fixed,...custom].sort((a,b)=>a.date-b.date).slice(0,4),wrap=$('#countdown-list');if(!wrap)return;wrap.innerHTML=items.map(item=>{const days=Math.max(0,Math.ceil((item.date-Date.now())/86400000)),date=`${item.date.getFullYear()}.${String(item.date.getMonth()+1).padStart(2,'0')}.${String(item.date.getDate()).padStart(2,'0')}`;return `<div class="countdown-item"><time>${String(item.date.getMonth()+1).padStart(2,'0')}<br>月</time><span><b>${esc(item.name)}</b><small>${date}</small></span><strong><i>${days}</i>天${item.fixed?'':` <button data-remove-countdown="${item.index}" aria-label="删除${esc(item.name)}">×</button>`}</strong></div>`}).join('')}
function openCountdownForm(){openInfo('添加自定义节点','<div class="custom-countdown-form"><label>节点名称<input id="countdown-name" maxlength="12" placeholder="例如：新品首发"></label><label>日期<input id="countdown-date" type="date"></label><button class="primary" id="save-countdown">保存节点</button></div>')}
function renderTitleCheck(){const value=$('#title-input').value,weighted=[...value].reduce((sum,ch)=>sum+(/[\u3400-\u9fff\uff01-\uff60]/.test(ch)?2:1),0),chinese=(value.match(/[\u3400-\u9fff]/g)||[]).length,remaining=60-weighted,status=$('#title-status');$('#title-weighted').textContent=weighted;$('#title-chinese').textContent=chinese;$('#title-remaining').textContent=remaining;status.className='checker-status '+(!value?'':weighted<=60?'good':'warn');status.textContent=!value?'等待输入':weighted<=60?'长度合适':'超出 '+Math.abs(remaining)+' 字符';$('#title-remaining').style.color=remaining<0?'var(--red)':''}
const WORKSPACE_KEY='boundary-workspace-v2';
const WORKSPACE_DEFAULTS={order:['tools','countdown','title','memo','intel'],modules:{tools:{title:'常用入口',cols:8,rows:7,links:[]},countdown:{title:'关键节点',cols:4,rows:7,links:[]},title:{title:'标题长度检查',cols:8,rows:6,links:[]},memo:{title:'今日运营便签',cols:4,rows:6,links:[]},intel:{title:'国内电商情报',cols:12,rows:7,links:[]}}};
let layoutEditing=false,draggedLayoutCard=null,workspaceState=null,resizeSession=null;
function dashboardCards(){return $$('.dashboard-grid [data-layout-card]')}
function cloneDefaults(){return JSON.parse(JSON.stringify(WORKSPACE_DEFAULTS))}
function clamp(n,min,max){return Math.max(min,Math.min(max,n))}
function loadWorkspace(){let saved=localRead(WORKSPACE_KEY,null),state=cloneDefaults();if(!saved){const legacy=localRead('boundary-dashboard-layout',null),map={compact:4,standard:6,wide:8,full:12};if(legacy){state.order=legacy.order||state.order;Object.entries(legacy.sizes||{}).forEach(([id,size])=>{if(state.modules[id])state.modules[id].cols=map[size]||state.modules[id].cols})}return state}state.order=Array.isArray(saved.order)?saved.order:state.order;for(const[id,mod]of Object.entries(saved.modules||{})){if(!mod||typeof mod!=='object')continue;state.modules[id]={...(state.modules[id]||{}),title:String(mod.title||state.modules[id]?.title||'自定义模块').slice(0,30),cols:clamp(Number(mod.cols)||6,3,12),rows:clamp(Number(mod.rows)||6,4,16),links:Array.isArray(mod.links)?mod.links.slice(0,40):[],custom:Boolean(mod.custom)}}for(const id of WORKSPACE_DEFAULTS.order)if(!state.order.includes(id))state.order.push(id);return state}
function moduleState(id){return workspaceState.modules[id]}
function safeUrl(value){let url=String(value||'').trim();if(!url)return null;if(!/^[a-z][a-z0-9+.-]*:\/\//i.test(url))url='https://'+url;try{const parsed=new URL(url);return ['http:','https:'].includes(parsed.protocol)?parsed.href:null}catch{return null}}
function createCustomCard(id){const card=document.createElement('section');card.className='dash-card layout-card custom-workspace-card';card.dataset.layoutCard=id;card.innerHTML='<div class="layout-card-body"><div class="dash-card-head"><div><span>自定义工作区</span><h2>自定义模块</h2></div><small>我的快捷入口</small></div><div class="workspace-link-zone custom-only"><div class="workspace-links"></div></div></div>';return card}
function ensureCardShell(card){if(card.querySelector(':scope > .layout-card-body'))return;const body=document.createElement('div');body.className='layout-card-body';[...card.childNodes].forEach(node=>body.append(node));card.append(body)}
function cardTools(id,custom){return `<div class="layout-card-tools" aria-label="模块设置"><button class="layout-grip" draggable="true" title="拖动模块" aria-label="拖动模块">⠿</button><button data-card-edit="${id}" title="修改名称">✎ 名称</button><button data-link-add="${id}" title="添加网址">＋ 网址</button><button class="layout-move" data-layout-move="-1" title="向前移动">↑</button><button class="layout-move" data-layout-move="1" title="向后移动">↓</button>${custom?`<button class="layout-delete" data-card-delete="${id}" title="删除模块">×</button>`:''}</div><button class="layout-resize" aria-label="拖动缩放模块" title="拖动自由缩放"><span></span></button><span class="layout-size-readout"></span>`}
function ensureLinkZone(card){if(card.querySelector('.workspace-link-zone'))return;card.querySelector('.layout-card-body').insertAdjacentHTML('beforeend','<div class="workspace-link-zone"><div class="workspace-link-label">我的入口</div><div class="workspace-links"></div></div>')}
function renderModuleLinks(id){const card=document.querySelector(`[data-layout-card="${CSS.escape(id)}"]`),wrap=card?.querySelector('.workspace-links'),mod=moduleState(id);if(!wrap||!mod)return;wrap.innerHTML=mod.links.length?mod.links.map((link,index)=>{const url=safeUrl(link.url)||'#',name=esc(String(link.name||'未命名入口'));let fallback='网址';try{fallback=new URL(url).hostname||fallback}catch{}const desc=esc(String(link.description||fallback));return `<div class="workspace-link-item"><a class="workspace-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer"><i>${esc(String(link.name||'网').trim().charAt(0)||'网')}</i><span><b>${name}</b><small>${desc}</small></span><em>打开 ↗</em></a><div class="workspace-link-actions"><button data-link-move="-1" data-card-id="${id}" data-link-index="${index}" title="上移">↑</button><button data-link-move="1" data-card-id="${id}" data-link-index="${index}" title="下移">↓</button><button data-link-edit="${index}" data-card-id="${id}">编辑</button><button data-link-delete="${index}" data-card-id="${id}">删除</button></div></div>`}).join(''):`<button class="empty-link-button" data-link-add="${id}">＋ 添加第一个网址</button>`}
function applyCardGeometry(card,mod){card.style.setProperty('--card-cols',mod.cols);card.style.setProperty('--card-rows',mod.rows);const readout=card.querySelector('.layout-size-readout');if(readout)readout.textContent=`${mod.cols}列 × ${mod.rows}格`}
function prepareWorkspaceCard(card){const id=card.dataset.layoutCard,mod=moduleState(id);ensureCardShell(card);if(!card.querySelector(':scope > .layout-card-tools'))card.insertAdjacentHTML('afterbegin',cardTools(id,mod.custom));ensureLinkZone(card);const heading=card.querySelector('.dash-card-head h2');if(heading)heading.textContent=mod.title;applyCardGeometry(card,mod);renderModuleLinks(id)}
function applyWorkspace(){const grid=$('.dashboard-grid');for(const[id,mod]of Object.entries(workspaceState.modules)){if(mod.custom&&!grid.querySelector(`[data-layout-card="${CSS.escape(id)}"]`))grid.append(createCustomCard(id))}dashboardCards().forEach(card=>{const id=card.dataset.layoutCard;if(!workspaceState.modules[id])card.remove()});const cards=new Map(dashboardCards().map(card=>[card.dataset.layoutCard,card]));workspaceState.order=workspaceState.order.filter(id=>cards.has(id));for(const id of cards.keys())if(!workspaceState.order.includes(id))workspaceState.order.push(id);workspaceState.order.forEach(id=>grid.append(cards.get(id)));dashboardCards().forEach(prepareWorkspaceCard)}
function saveWorkspace(){workspaceState.order=dashboardCards().map(card=>card.dataset.layoutCard);localWrite(WORKSPACE_KEY,workspaceState)}
function moveLayoutCard(card,step){const cards=dashboardCards(),index=cards.indexOf(card),target=cards[index+step];if(!target)return;const grid=$('.dashboard-grid');if(step<0)grid.insertBefore(card,target);else grid.insertBefore(target,card);saveWorkspace()}
function setLayoutEditing(active){layoutEditing=active;$('#dashboard-view').classList.toggle('layout-editing',active);$('#layout-edit').classList.toggle('active',active);$('#layout-edit').innerHTML=active?'✓ 完成设置':'<span>⚙</span> 工作台设置';$('#layout-reset').hidden=!active;$('#layout-add-card').hidden=!active;$('#workspace-edit-tip').hidden=!active;if(active)toast('拖动模块移动位置，拖动右下角自由缩放')}
function resetDashboardLayout(){if(!confirm('恢复默认布局会删除自定义模块、名称和网址，确定继续吗？'))return;localStorage.removeItem(WORKSPACE_KEY);location.reload()}
function openCardEditor(id){const mod=moduleState(id);openInfo('修改模块名称',`<div class="workspace-form"><label>模块名称<input id="workspace-card-title" maxlength="30" value="${esc(mod.title)}" placeholder="例如：每日运营"></label><p>名称只保存在当前浏览器。</p><button class="primary" id="workspace-save-card" data-card-id="${id}">保存名称</button></div>`);setTimeout(()=>$('#workspace-card-title')?.focus(),0)}
function openLinkEditor(id,index=-1){const link=index>=0?moduleState(id).links[index]:{name:'',url:'',description:''};openInfo(index>=0?'编辑网址':'添加网址',`<div class="workspace-form"><label>入口名称<input id="workspace-link-name" maxlength="24" value="${esc(link.name||'')}" placeholder="例如：生意参谋"></label><label>网址<input id="workspace-link-url" value="${esc(link.url||'')}" placeholder="https://..."></label><label>用途说明（可选）<input id="workspace-link-desc" maxlength="40" value="${esc(link.description||'')}" placeholder="例如：查看市场与店铺数据"></label><button class="primary" id="workspace-save-link" data-card-id="${id}" data-link-index="${index}">保存网址</button></div>`);setTimeout(()=>$('#workspace-link-name')?.focus(),0)}
function addCustomModule(){const id='custom-'+Date.now().toString(36);workspaceState.modules[id]={title:'我的工作模块',cols:4,rows:6,links:[],custom:true};workspaceState.order.push(id);applyWorkspace();saveWorkspace();openCardEditor(id)}
function initWorkspaceResize(){document.addEventListener('pointerdown',e=>{const handle=e.target.closest('.layout-resize');if(!layoutEditing||!handle||innerWidth<=850)return;const card=handle.closest('.layout-card'),grid=$('.dashboard-grid'),id=card.dataset.layoutCard,mod=moduleState(id),gridRect=grid.getBoundingClientRect(),cardRect=card.getBoundingClientRect(),gap=parseFloat(getComputedStyle(grid).columnGap)||14;resizeSession={handle,card,id,startX:e.clientX,startY:e.clientY,startW:cardRect.width,startH:cardRect.height,colUnit:(gridRect.width-gap*11)/12,rowUnit:46,gap};handle.setPointerCapture(e.pointerId);card.classList.add('resizing');e.preventDefault()});document.addEventListener('pointermove',e=>{if(!resizeSession)return;const s=resizeSession,mod=moduleState(s.id),width=s.startW+e.clientX-s.startX,height=s.startH+e.clientY-s.startY;mod.cols=clamp(Math.round((width+s.gap)/(s.colUnit+s.gap)),3,12);mod.rows=clamp(Math.round((height+s.gap)/s.rowUnit),4,16);applyCardGeometry(s.card,mod)});document.addEventListener('pointerup',()=>{if(!resizeSession)return;resizeSession.card.classList.remove('resizing');resizeSession=null;saveWorkspace()})}
function initLayoutEditor(){workspaceState=loadWorkspace();applyWorkspace();const grid=$('.dashboard-grid');grid.addEventListener('dragstart',e=>{const grip=e.target.closest('.layout-grip');if(!layoutEditing||!grip){e.preventDefault();return}draggedLayoutCard=grip.closest('.layout-card');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedLayoutCard.dataset.layoutCard);requestAnimationFrame(()=>draggedLayoutCard.classList.add('dragging'))});grid.addEventListener('dragover',e=>{if(!draggedLayoutCard)return;e.preventDefault();$$('.layout-card.drag-target').forEach(card=>card.classList.remove('drag-target'));const target=e.target.closest('.layout-card');if(target&&target!==draggedLayoutCard)target.classList.add('drag-target')});grid.addEventListener('drop',e=>{if(!draggedLayoutCard)return;e.preventDefault();const target=e.target.closest('.layout-card');if(target&&target!==draggedLayoutCard){const rect=target.getBoundingClientRect(),before=e.clientY<rect.top+rect.height/2;grid.insertBefore(draggedLayoutCard,before?target:target.nextSibling)}saveWorkspace()});grid.addEventListener('dragend',()=>{dashboardCards().forEach(card=>card.classList.remove('dragging','drag-target'));draggedLayoutCard=null});initWorkspaceResize()}
function initDashboard(){showView(location.hash==='#demand'?'demand':location.hash==='#keywords'?'keywords':location.hash==='#price'?'price':'dashboard',false);renderRecentTools();renderCountdowns();$('#ops-memo').value=localRead('boundary-ops-memo','');renderTitleCheck();initLayoutEditor();setInterval(renderCountdowns,3600000)}

document.addEventListener('click',async e=>{const viewLink=e.target.closest('[data-view]');if(viewLink){e.preventDefault();showView(viewLink.dataset.view);return}const openView=e.target.closest('[data-open-view]');if(openView){trackTool(openView.dataset.toolId,openView.dataset.toolName,'',openView.dataset.openView);showView(openView.dataset.openView);return}const provider=e.target.closest('[data-search-provider]');if(provider){activeSearchProvider=provider.dataset.searchProvider;$$('[data-search-provider]').forEach(b=>b.classList.toggle('active',b===provider));$('#ops-search-input').focus();return}const tool=e.target.closest('[data-tool-id]');if(tool&&tool.href)trackTool(tool.dataset.toolId,tool.dataset.toolName,tool.href);const recentButton=e.target.closest('[data-recent-tool]');if(recentButton){const item=localRead('boundary-recent-tools',[])[+recentButton.dataset.recentTool];if(!item)return;if(item.view)showView(item.view);else if(item.url)window.open(item.url,'_blank','noopener');return}if(e.target.closest('#add-countdown'))openCountdownForm();if(e.target.closest('#save-countdown')){const name=$('#countdown-name').value.trim(),date=$('#countdown-date').value;if(!name||!date){toast('请填写节点名称和日期');return}const items=localRead('boundary-countdowns',[]);items.push({name,date});localWrite('boundary-countdowns',items);$('#info-overlay').hidden=true;renderCountdowns();toast('节点已保存到当前浏览器')}const remove=e.target.closest('[data-remove-countdown]');if(remove){const items=localRead('boundary-countdowns',[]);items.splice(+remove.dataset.removeCountdown,1);localWrite('boundary-countdowns',items);renderCountdowns()}if(e.target.closest('#clear-title')){$('#title-input').value='';renderTitleCheck();$('#title-input').focus()}if(e.target.closest('#copy-title')){const text=$('#title-input').value;if(!text){toast('请先输入标题');return}try{await navigator.clipboard.writeText(text);toast('标题已复制')}catch{toast('复制失败，请手动复制')}}if(e.target.closest('#clear-memo')){$('#ops-memo').value='';localWrite('boundary-ops-memo','');$('#memo-status').textContent='已清空';$('#memo-status').classList.add('saved')}});
document.addEventListener('click',e=>{if(e.target.closest('#layout-edit')){setLayoutEditing(!layoutEditing);return}if(e.target.closest('#layout-reset')){resetDashboardLayout();return}if(e.target.closest('#layout-add-card')){addCustomModule();return}const move=e.target.closest('[data-layout-move]');if(move){moveLayoutCard(move.closest('.layout-card'),+move.dataset.layoutMove);return}const cardEdit=e.target.closest('[data-card-edit]');if(cardEdit){openCardEditor(cardEdit.dataset.cardEdit);return}const addLink=e.target.closest('[data-link-add]');if(addLink){openLinkEditor(addLink.dataset.linkAdd);return}const editLink=e.target.closest('[data-link-edit]');if(editLink){openLinkEditor(editLink.dataset.cardId,+editLink.dataset.linkEdit);return}const linkMove=e.target.closest('[data-link-move]');if(linkMove){const mod=moduleState(linkMove.dataset.cardId),index=+linkMove.dataset.linkIndex,target=index+(+linkMove.dataset.linkMove);if(target>=0&&target<mod.links.length){[mod.links[index],mod.links[target]]=[mod.links[target],mod.links[index]];renderModuleLinks(linkMove.dataset.cardId);saveWorkspace()}return}const deleteLink=e.target.closest('[data-link-delete]');if(deleteLink){const mod=moduleState(deleteLink.dataset.cardId);mod.links.splice(+deleteLink.dataset.linkDelete,1);renderModuleLinks(deleteLink.dataset.cardId);saveWorkspace();toast('网址已删除');return}const deleteCard=e.target.closest('[data-card-delete]');if(deleteCard){const id=deleteCard.dataset.cardDelete;if(confirm(`删除“${moduleState(id).title}”模块？`)){delete workspaceState.modules[id];workspaceState.order=workspaceState.order.filter(item=>item!==id);document.querySelector(`[data-layout-card="${CSS.escape(id)}"]`)?.remove();saveWorkspace();toast('模块已删除')}return}const saveCard=e.target.closest('#workspace-save-card');if(saveCard){const title=$('#workspace-card-title').value.trim();if(!title){toast('请输入模块名称');return}const id=saveCard.dataset.cardId;moduleState(id).title=title;document.querySelector(`[data-layout-card="${CSS.escape(id)}"] .dash-card-head h2`).textContent=title;saveWorkspace();$('#info-overlay').hidden=true;toast('模块名称已保存');return}const saveLink=e.target.closest('#workspace-save-link');if(saveLink){const name=$('#workspace-link-name').value.trim(),url=safeUrl($('#workspace-link-url').value),description=$('#workspace-link-desc').value.trim();if(!name||!url){toast('请填写入口名称和有效网址');return}const id=saveLink.dataset.cardId,index=+saveLink.dataset.linkIndex,link={name,url,description};if(index>=0)moduleState(id).links[index]=link;else moduleState(id).links.push(link);renderModuleLinks(id);saveWorkspace();$('#info-overlay').hidden=true;toast(index>=0?'网址已更新':'网址已添加');return}});
document.addEventListener('dblclick',e=>{if(!layoutEditing)return;const heading=e.target.closest('.layout-card .dash-card-head h2');if(heading)openCardEditor(heading.closest('.layout-card').dataset.layoutCard)});
document.addEventListener('click',e=>{if(!layoutEditing)return;const interactive=e.target.closest('.layout-card a,.layout-card button,.layout-card textarea');if(interactive&&!interactive.closest('.layout-card-tools')&&!interactive.matches('.empty-link-button')&&!interactive.closest('.workspace-link-actions')){e.preventDefault();e.stopImmediatePropagation()}},true);
$('#ops-search-form').addEventListener('submit',e=>{e.preventDefault();const query=$('#ops-search-input').value.trim();if(!query){toast('请输入搜索内容');$('#ops-search-input').focus();return}if(activeSearchProvider==='internal'){showView('keywords');$('#root-query').value=query;state.rootPage=1;if(DATA)renderRoots();$('#root-query').focus();return}window.open(SEARCH_URLS[activeSearchProvider]+encodeURIComponent(query),'_blank','noopener')});
$('#title-input').addEventListener('input',renderTitleCheck);
let memoTimer;$('#ops-memo').addEventListener('input',e=>{clearTimeout(memoTimer);$('#memo-status').textContent='保存中…';$('#memo-status').classList.remove('saved');memoTimer=setTimeout(()=>{localWrite('boundary-ops-memo',e.target.value);$('#memo-status').textContent='已保存';$('#memo-status').classList.add('saved')},250)});
window.addEventListener('hashchange',()=>showView(location.hash==='#demand'?'demand':location.hash==='#keywords'?'keywords':location.hash==='#price'?'price':'dashboard',false));
initDashboard();
